    user_id: userId,
    date: dateStr,
    kondition: t("kondition"),
    styrka: t("styrka"),
    plugg: t("plugg"),
    ekonomi: t("ekonomi"),
    valm\u00E5ende: t("halsa"),
    // merged Sömn+Hälsa — column predates the merge
    fardigheter: t("fardigheter"),
    score_version: SCORE_VERSION
